uint32_t gw_mex_bridge_count(void)
{
    return (uint32_t)(sizeof gw_mex_bridge_table / sizeof gw_mex_bridge_table[0]);
}

uint32_t gw_mex_bridge_lookup(uint32_t guest_addr, int *kind)
{
    uint32_t lo = 0;
    uint32_t hi = gw_mex_bridge_count();
    if (kind != NULL) { *kind = 0; }
    while (lo < hi) {
        uint32_t mid = lo + (hi - lo) / 2;
        uint32_t g = gw_mex_bridge_table[mid].guest;
        if (g == guest_addr) {
            if (kind != NULL) { *kind = gw_mex_bridge_table[mid].kind; }
            return gw_mex_bridge_table[mid].native;
        }
        if (g < guest_addr) { lo = mid + 1; } else { hi = mid; }
    }
    return 0;
}
